import assert from 'node:assert/strict';
import {checkAppWebhookFieldStatus} from '../../app/lib/whatsapp-app-webhook-check.ts';
import {readFileSync} from 'node:fs';
const args={appId:'1234567890123',appSecret:'AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA',graphVersion:'v23.0'};
const callback='https://zeshu.in/api/webhooks/meta-whatsapp';
const fake=(row,code=200)=>new Response(JSON.stringify(code===200?{data:[row]}:{error:{code:190,message:'DO_NOT_SHOW_THIS_SECRET'}}),{status:code});
const passing=await checkAppWebhookFieldStatus({...args,request:async(url,init)=>{
 assert.equal(url,'https://graph.facebook.com/v23.0/1234567890123/subscriptions');
 assert.equal(init.method,'GET');
 assert.equal(init.headers.Authorization,'Bearer '+args.appId+'|'+args.appSecret);
 assert.equal(init.redirect,'manual');
 return fake({object:'whatsapp_business_account',callback_url:callback,fields:['messages'],active:true});
}});
assert.deepEqual(passing,{status:'READY',messagesFieldSubscribed:true,callbackMatches:true});
assert.ok(!JSON.stringify(passing).includes(args.appSecret));
const missingField=await checkAppWebhookFieldStatus({...args,request:async()=>fake({object:'whatsapp_business_account',callback_url:callback,fields:['phone_number_name_update'],active:true})});
assert.equal(missingField.status,'MESSAGES_NOT_SUBSCRIBED');
const wrongUrl=await checkAppWebhookFieldStatus({...args,request:async()=>fake({object:'whatsapp_business_account',callback_url:'https://other.example/hook',fields:['messages'],active:true})});
assert.equal(wrongUrl.status,'CALLBACK_MISMATCH');
const inactive=await checkAppWebhookFieldStatus({...args,request:async()=>fake({object:'whatsapp_business_account',callback_url:callback,fields:['messages'],active:false})});
assert.equal(inactive.status,'INACTIVE');
const missing=await checkAppWebhookFieldStatus({...args,request:async()=>new Response(JSON.stringify({data:[]}),{status:200})});
assert.equal(missing.status,'SUBSCRIPTION_MISSING');
const malformed=await checkAppWebhookFieldStatus({...args,appSecret:'invalid\nheader',request:async()=>{throw Error('must not call');}});
assert.equal(malformed.status,'INVALID_CONFIG');
const forbidden=await checkAppWebhookFieldStatus({...args,request:async()=>fake({},400)});
assert.equal(forbidden.status,'TOKEN_UNAUTHORIZED');
assert.ok(!JSON.stringify(forbidden).includes('DO_NOT_SHOW_THIS_SECRET'));
const offline=await checkAppWebhookFieldStatus({...args,request:async()=>{throw Error('PRIVATE_NET_ADDRESS');}});
assert.equal(offline.status,'META_UNAVAILABLE');
assert.ok(!JSON.stringify(offline).includes('PRIVATE_NET_ADDRESS'));
const endpoint=readFileSync('app/api/admin/whatsapp/app-webhook/route.ts','utf8');
assert(endpoint.includes('authorizeWhatsAppInboxAdmin(request)'),'Check must require administrator authentication');
assert(!endpoint.includes("method:'POST'"),'No Meta write method permitted');
assert(endpoint.includes('getRuntimeEnvValue'),'Secrets must only come from server runtime');
const inbox=readFileSync('app/admin/whatsapp/inbox/page.tsx','utf8');
assert(inbox.includes('Check messages field & callback URL'),'Inbox must expose check');
console.log('PASS: admin-only read-only app-level WhatsApp messages webhook/URL verification and safe Meta errors.');
